patch.replace:
def _load_obs(limit: int = 4000):
    """Real labeled setups as (sanitized feature-dict, finite clipped return), chronological order.
    Skips rows with non-finite returns (delisted/no-price) and zeroes any non-finite feature.
    Uses a sliding window over the full file so the Forge always trains on the most recent
    `limit` setups — older resolved rows are dropped instead of kept forever, which raises
    learning velocity by keeping the candidate search aligned with current market regime."""
    rows = []
    try:
        with open(RESOLVED) as f:
            for line in f:
                try:
                    o = json.loads(line)
                    feat, ret = o.get("feat") or {}, o.get("ret")
                    if not feat or ret is None:
                        continue
                    ret = float(ret)
                    if not math.isfinite(ret):
                        continue
                    ret = max(-RET_CLIP, min(RET_CLIP, ret))
                    clean = {}
                    for k, v in feat.items():
                        try:
                            fv = float(v)
                            clean[k] = fv if math.isfinite(fv) else 0.0
                        except Exception:
                            clean[k] = 0.0
                    rows.append((clean, ret))
                except Exception:
                    continue
    except FileNotFoundError:
        return []
    # Sliding window: keep only the most recent `limit` rows so the Forge's search space
    # reflects the latest labeled setups, improving learning velocity and calibration freshness.
    if len(rows) > limit:
        rows = rows[-limit:]
    return rows

